import pyomo.environ as pyo

DATA = {
    "routes": ["X", "Y", "Z"],
    "cost": {"X": 10, "Y": 20, "Z": 30},
    "total_cap": 1000,
    "twice_X_minus_Y": 200,   # 2*x_X - x_Y >= 200
    "coef_X_service": 2,
    "Y_minus_Z_max": 50,      # x_Y - x_Z <= 50
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.R = pyo.Set(initialize=d["routes"])

    def xbounds(m, i):
        return (0, None)

    model.x = pyo.Var(
        model.R,
        domain=pyo.NonNegativeIntegers,
        bounds=xbounds,
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.R)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def total_cap_rule(m):
        return sum(m.x[i] for i in m.R) <= d["total_cap"]

    model.total_cap = pyo.Constraint(rule=total_cap_rule)

    def service_rule(m):
        return (
            d["coef_X_service"] * m.x["X"] - m.x["Y"]
            >= d["twice_X_minus_Y"]
        )

    model.service = pyo.Constraint(rule=service_rule)

    def balance_rule(m):
        return m.x["Y"] - m.x["Z"] <= d["Y_minus_Z_max"]

    model.balance = pyo.Constraint(rule=balance_rule)

    return model
